-- Preserve all existing project dates while allowing new drafts without a
-- civil anchor. The calculated finish remains nullable until a valid CPM run.
ALTER TABLE "projects" ALTER COLUMN "plannedStart" DROP NOT NULL;
--> statement-breakpoint
ALTER TABLE "projects" ALTER COLUMN "plannedFinish" DROP NOT NULL;
--> statement-breakpoint

CREATE TABLE "activity_schedule_updates" (
  "id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  "projectId" integer NOT NULL,
  "activityId" integer NOT NULL,
  "versionId" integer,
  "positionDate" date NOT NULL,
  "status" varchar(24) NOT NULL,
  "actualStartDate" date,
  "actualFinishDate" date,
  "remainingDurationDays" integer,
  "forecastFinishDate" date,
  "note" text,
  "blockerReason" text,
  "evidenceRef" varchar(500),
  "supersedesId" integer,
  "authorUserId" integer NOT NULL,
  "createdAt" timestamp with time zone DEFAULT now() NOT NULL,
  CONSTRAINT "activity_schedule_updates_status_valid"
    CHECK ("status" IN ('nao_iniciada', 'em_andamento', 'concluida', 'bloqueada')),
  CONSTRAINT "activity_schedule_updates_remaining_positive"
    CHECK ("remainingDurationDays" IS NULL OR "remainingDurationDays" > 0),
  CONSTRAINT "activity_schedule_updates_project_fk"
    FOREIGN KEY ("projectId") REFERENCES "projects"("id"),
  CONSTRAINT "activity_schedule_updates_activity_fk"
    FOREIGN KEY ("activityId") REFERENCES "schedule_activities"("id"),
  CONSTRAINT "activity_schedule_updates_version_fk"
    FOREIGN KEY ("versionId") REFERENCES "project_plan_versions"("id"),
  CONSTRAINT "activity_schedule_updates_supersedes_fk"
    FOREIGN KEY ("supersedesId") REFERENCES "activity_schedule_updates"("id"),
  CONSTRAINT "activity_schedule_updates_author_fk"
    FOREIGN KEY ("authorUserId") REFERENCES "users"("id")
);
--> statement-breakpoint
CREATE UNIQUE INDEX "activity_schedule_updates_single_correction_idx"
  ON "activity_schedule_updates" USING btree ("supersedesId")
  WHERE "supersedesId" IS NOT NULL;
--> statement-breakpoint
CREATE INDEX "activity_schedule_updates_project_activity_idx"
  ON "activity_schedule_updates" USING btree ("projectId", "activityId", "positionDate");
--> statement-breakpoint
CREATE INDEX "activity_schedule_updates_version_idx"
  ON "activity_schedule_updates" USING btree ("versionId");
--> statement-breakpoint

-- New public tables inherit Supabase's default privileges for anon and
-- authenticated. The activity history contains project data and must remain
-- backend-only. The runtime role is append-only for this table.
REVOKE ALL PRIVILEGES ON TABLE "activity_schedule_updates" FROM PUBLIC;
--> statement-breakpoint
DO $$
DECLARE
  role_name text;
BEGIN
  FOREACH role_name IN ARRAY ARRAY['anon', 'authenticated', 'service_role', 'arquimedes_app'] LOOP
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = role_name) THEN
      EXECUTE format(
        'REVOKE ALL PRIVILEGES ON TABLE %I FROM %I',
        'activity_schedule_updates',
        role_name
      );
      EXECUTE format(
        'REVOKE ALL PRIVILEGES ON SEQUENCE %I FROM %I',
        'activity_schedule_updates_id_seq',
        role_name
      );
    END IF;
  END LOOP;

  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'arquimedes_app') THEN
    GRANT SELECT, INSERT ON TABLE "activity_schedule_updates" TO arquimedes_app;
    GRANT USAGE ON SEQUENCE "activity_schedule_updates_id_seq" TO arquimedes_app;
  END IF;
END $$;
